/** Core-team series whose posts live in MySQL (served by /api). Metadata is generated by scripts/import-ssd.py. */
import libraryJson from '../data/library.json';
import type { DoodleName, TopicId } from '../data/types';

export interface LibrarySeries {
  slug: string;
  title: string;
  tagline: string;
  subject: string;
  topic: TopicId;
  doodle: DoodleName;
  color: { from: string; to: string; ink: 'light' | 'dark' };
  description: string;
  launchedAt: string;
}

export const library = (libraryJson as LibrarySeries[]).slice().sort((a, b) => a.launchedAt.localeCompare(b.launchedAt));
export const libraryTitles: Record<string, string> = Object.fromEntries(library.map((s) => [s.slug, s.title]));
